        int max_a = -1;
        for (int i = 0; i < n; i++) {
            cin >> a[i];
            max_a = max(max_a, a[i]);
        }
        int l = 0, r = max_a + 1;
        while (l + 1 < r) {
            int mid = (l + r) / 2;
            f(n, mid, pref);
            reverse(a, a + n);
            f(n, mid, suf);
            reverse(a, a + n);
            reverse(suf, suf + n);
            int mx = -1;
            for (int i = 0; i < n; i++) {
                if (a[i] >= mid)
                    mx = max(mx, pref[i] + suf[i] - 1);
            }
            if (n - mx <= k)
                l = mid;
            else
                r = mid;
        }
        cout << l << '\n';
    }
